def transform(grid):
    # Pattern: Scattered colors (target) transform to structured colors (source)
    # 1s (scattered) → 5s (structured T-shape)
    result = [row[:] for row in grid]
    for i in range(len(result)):
        for j in range(len(result[i])):
            if result[i][j] == 1:
                result[i][j] = 5
    return result
